{"name":"ucsi_connector_change","qualified_name":"workspace-linux.drivers.usb.typec.ucsi.ucsi.ucsi_connector_change","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/ucsi/ucsi.c","start_line":1371,"end_line":1382,"source":"void ucsi_connector_change(struct ucsi *ucsi, u8 num)
{
	struct ucsi_connector *con = &ucsi->connector[num - 1];

	if (!(ucsi->ntfy & UCSI_ENABLE_NTFY_CONNECTOR_CHANGE)) {
		dev_dbg(ucsi->dev, "Early connector change event\n");
		return;
	}

	if (!test_and_set_bit(EVENT_PENDING, &ucsi->flags))
		schedule_work(&con->work);
}
