{"name":"ucsi_notify_common","qualified_name":"workspace-linux.drivers.usb.typec.ucsi.ucsi.ucsi_notify_common","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/ucsi/ucsi.c","start_line":40,"end_line":62,"source":"void ucsi_notify_common(struct ucsi *ucsi, u32 cci)
{
	/* Ignore bogus data in CCI if busy indicator is set. */
	if (cci & UCSI_CCI_BUSY)
		return;

	if (UCSI_CCI_CONNECTOR(cci)) {
		if (!ucsi->cap.num_connectors ||
		    UCSI_CCI_CONNECTOR(cci) <= ucsi->cap.num_connectors)
			ucsi_connector_change(ucsi, UCSI_CCI_CONNECTOR(cci));
		else
			dev_err(ucsi->dev, "bogus connector number in CCI: %lu\n",
				UCSI_CCI_CONNECTOR(cci));
	}

	if (cci & UCSI_CCI_ACK_COMPLETE &&
	    test_and_clear_bit(ACK_PENDING, &ucsi->flags))
		complete(&ucsi->complete);

	if (cci & UCSI_CCI_COMMAND_COMPLETE &&
	    test_and_clear_bit(COMMAND_PENDING, &ucsi->flags))
		complete(&ucsi->complete);
}
